/**
 * The on-disk shape of the static data, in one place.
 *
 * Everything under data/ is generated by the pipeline and read by the app, so
 * both sides agree on the field names through these helpers instead of
 * duplicating the format.
 *
 *   data/meta.json       counts, sources, licence, build stamp
 *   data/catalog.json    lean index for the recipe grid
 *   data/recipes/NNN.json  full recipes, 100 per shard
 *   data/products.json   canonical ingredient -> matched AH products + nutrition
 *   data/prices.json     product id -> current price
 */

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

// Paths are module-relative so the scripts work from any working directory
// (`node scripts/build-recipes.js` from the repo root, or from scripts/).
const SCRIPTS_DIR = dirname(dirname(fileURLToPath(import.meta.url)));
export const DATA_DIR = resolve(SCRIPTS_DIR, '..', 'data');
export const SCRIPT_FILE = name => resolve(SCRIPTS_DIR, name);
export const SHARD_SIZE = 100;
export const RECIPE_DATA_VERSION = 1;

/**
 * Writes a JSON file with stable formatting and returns its byte size.
 * @param {string} path
 * @param {Object|Array} value
 * @returns {number}
 */
export function writeJson(path, value) {
  const text = `${JSON.stringify(value)}\n`;
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, text);
  return Buffer.byteLength(text);
}

/**
 * Stable id for a recipe built from its title, so reruns keep the same ids.
 * @param {string} title
 * @returns {string}
 */
export function recipeId(title) {
  const slug = String(title || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60);
  return `r-${slug || 'recipe'}`;
}

/**
 * Shard file name for a recipe index.
 * @param {number} index
 * @returns {string}
 */
export function shardName(index) {
  return `${String(Math.floor(index / SHARD_SIZE)).padStart(3, '0')}.json`;
}

/**
 * The lean catalog entry for one recipe.
 * @param {Object} recipe
 * @returns {Object}
 */
export function catalogEntry(recipe) {
  return {
    id: recipe.id,
    shard: recipe.shard,
    title: recipe.title,
    titleEn: recipe.titleEn,
    description: recipe.description,
    descriptionEn: recipe.descriptionEn,
    cuisine: recipe.cuisine,
    mealType: recipe.mealType,
    dishType: recipe.dishType,
    prepTimeMinutes: recipe.prepTimeMinutes,
    baseServings: recipe.baseServings,
    difficulty: recipe.difficulty,
    nutrition: recipe.nutrition,
    tags: recipe.tags,
    image: recipe.image,
    ingredientCount: recipe.ingredients.length,
    source: recipe.source,
    sourceUrl: recipe.sourceUrl || ''
  };
}

/**
 * Default meta block, including the licence the recipe corpus requires.
 * @param {Object} overrides
 * @returns {Object}
 */
export function metaBlock(overrides = {}) {
  return {
    version: RECIPE_DATA_VERSION,
    generatedAt: new Date().toISOString(),
    sources: [
      {
        name: 'Recipe Dataset (over 2M)',
        url: 'https://www.kaggle.com/datasets/wilmerarltstrmberg/recipe-dataset-over-2m',
        via: 'https://play.clickhouse.com (public playground, table `recipes`)',
        licence: 'CC BY-NC-SA 4.0',
        licenceUrl: 'https://creativecommons.org/licenses/by-nc-sa/4.0/',
        note: 'Curated to main-course dinner recipes; titles and steps are translated with a local model.'
      },
      {
        name: 'TheMealDB',
        url: 'https://www.themealdb.com',
        licence: 'Free for non-commercial use'
      },
      {
        name: 'Albert Heijn',
        url: 'https://www.ah.nl',
        note: 'Product names, pack sizes and prices via the public mobile API. Prices are a snapshot, not a live quote.'
      }
    ],
    ...overrides
  };
}
